(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.025-t*0.15)*8+Math.cos(mx*0.02+t*0.4)*6;
  const w2y = Math.cos(mx*0.022+t*0.18)*8+Math.sin(my*0.019-t*0.32)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.13,1.8,3.5]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    hrm+=Math.sin(d*f*0.5-t*sp*0.4+ph*0.3)*0.5;
  }
  const act=aS/8,inh=iS/8,h=hrm/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.6)+Math.cos(sx*0.07+sy*0.09-t*1.3))/2*0.3;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*2-t*2.1)*0.15+Math.sin(dist*0.03-ang*5+t*0.9)*0.15;
  const lap=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const cell=Math.tanh(lap*1.5)*0.3;
  const fine=Math.sin(sx*0.3+sy*0.2-t*3)*Math.cos(sx*0.2-sy*0.3+t*2.5)*0.1;
  const pre=act-inh*0.7+bg*0.3+sp1+sp2+h*0.4+fine;
  const reaction=Math.tanh(pre*2.2);
  const blend=reaction*0.65+cell*0.25+fine*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,35,85],[15,65,115],[20,100,135],[30,140,140],[60,170,120],[120,185,80],[190,190,60],[220,170,50],[230,130,55],[220,90,60],[190,60,55],[150,40,55],[100,25,50],[50,15,45],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.2)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
